from urllib.parse import urlparse
from litdata.streaming.client import S3Client
import os
import shutil
from queue import Queue  # I assume Queue is from the queue module
from pathlib import Path

def _upload_fn(upload_queue: Queue, remove_queue: Queue, cache_dir: str, output_dir: Dir) -> None:
    output_scheme = urlparse(output_dir).scheme

    if output_scheme == 's3':
        s3_client = S3Client(output_dir)
    else:
        output_dir = Path(output_dir)

    if not output_dir.is_dir():
        raise ValueError(f"Output directory '{output_dir}' is not a valid path")

    try:
        # Upload logic goes here
        while not upload_queue.empty():
            item = upload_queue.get()
            if item is None:
                # Termination signal, break out of the loop
                break
            if isinstance(item, tuple):
                temp_dir, file_path = item
                file_path = os.path.join(temp_dir, file_path)
            else:
                file_path = item

            # Adjust the local file path to be relative to the cache_dir
            if not file_path.startswith(cache_dir):
                file_path = os.path.join(cache_dir, os.path.relpath(file_path, start=cache_dir))

            if output_scheme == 's3':
                s3_client.upload(file_path)
            else:
                # Create the necessary directories
                output_dir.mkdir(parents=True, exist_ok=True)
                # Move the file to the target location, preserving the file name
                shutil.move(file_path, os.path.join(output_dir, os.path.basename(file_path)))
            remove_queue.put(file_path)
    except Exception as e:
        print(f"Error uploading files: {e}")
